def solve(n: int, links: list[list[int]], start: int, goal: int) -> int:
    graph = [[] for _ in range(n)]
    for a, b in links:
        graph[a].append(b)
        graph[b].append(a)
    distance = [-1]*n
    distance[start] = 0
    queue = [start]
    for u in queue:
        for v in graph[u]:
            if distance[v] == -1:
                distance[v] = distance[u]+1
                queue.append(v)
    return distance[goal]

