def solve(n: int, links: list[list[int]]) -> int:
    graph = [[] for _ in range(n)]
    for a, b in links:
        graph[a].append(b)
        graph[b].append(a)
    def far(start):
        dist = [-1]*n
        dist[start] = 0
        queue = [start]
        best = start
        for u in queue:
            if dist[u] > dist[best]:
                best = u
            for v in graph[u]:
                if dist[v] == -1:
                    dist[v] = dist[u]+1
                    queue.append(v)
        return best, dist[best]
    return far(far(0)[0])[1]

