def solve(n: int, routes: list[list[int]], start: int, goal: int) -> int:
    graph = [[] for _ in range(n)]
    for a, b, w in routes:
        graph[a].append((b, w))
    distance = [float('inf')]*(2*n)
    used = [False]*(2*n)
    distance[start*2] = 0
    for _ in range(2*n):
        u = -1
        for i in range(2*n):
            if not used[i] and (u == -1 or distance[i] < distance[u]):
                u = i
        if u == -1 or distance[u] == float('inf'):
            break
        used[u] = True
        state = u % 2
        for v, w in graph[u//2]:
            distance[v*2+state] = min(distance[v*2+state], distance[u]+w)
            if state == 0:
                distance[v*2+1] = min(distance[v*2+1], distance[u]+w//2)
    answer = min(distance[goal*2], distance[goal*2+1])
    return -1 if answer == float('inf') else answer

