def solve(n: int, links: list[list[int]]) -> list[list[int]]:
    graph = [[] for _ in range(n)]
    for edge, (a, b) in enumerate(links):
        graph[a].append((b, edge))
        graph[b].append((a, edge))
    time = [-1]*n
    low = [0]*n
    out = []
    tick = 0
    def visit(u, parent):
        nonlocal tick
        time[u] = low[u] = tick
        tick += 1
        for v, edge in graph[u]:
            if edge == parent:
                continue
            if time[v] >= 0:
                low[u] = min(low[u], time[v])
            else:
                visit(v, edge)
                low[u] = min(low[u], low[v])
                if low[v] > time[u]:
                    out.append([min(u,v), max(u,v)])
    for u in range(n):
        if time[u] < 0:
            visit(u, -1)
    return sorted(out)

