int R=grid.length,C=grid[0].length,MOD=1000000007;int[][][]dp=new int[R][C][permits+1];if(grid[0][0]<=permits)dp[0][0][grid[0][0]]=1;for(int r=0;r<R;r++)for(int c=0;c<C;c++){if(r==0&&c==0)continue;int cost=grid[r][c];for(int k=cost;k<=permits;k++)dp[r][c][k]=((r>0?dp[r-1][c][k-cost]:0)+(c>0?dp[r][c-1][k-cost]:0))%MOD;}int out=0;for(int x:dp[R-1][C-1])out=(out+x)%MOD;return out;
}

