function solve(prices, limit) {
const k=Math.min(limit,Math.floor(prices.length/2));let cash=Array(k+1).fill(0),hold=Array(k+1).fill(-Infinity);for(const price of prices){const nc=cash.slice(),nh=hold.slice();for(let t=1;t<=k;t++){nh[t]=Math.max(hold[t],cash[t-1]-price);nc[t]=Math.max(cash[t],hold[t]+price);}cash=nc;hold=nh;}return cash[k];
}

