public static int solve(int[] prices, int limit) {
int k=Math.min(limit,prices.length/2);int[]cash=new int[k+1],hold=new int[k+1];java.util.Arrays.fill(hold,-1000000000);for(int p:prices){int[]nc=cash.clone(),nh=hold.clone();for(int t=1;t<=k;t++){nh[t]=Math.max(hold[t],cash[t-1]-p);nc[t]=Math.max(cash[t],hold[t]+p);}cash=nc;hold=nh;}return cash[k];
}

